INSERT OR IGNORE INTO inspections (id,date,issue,cause,solution,assignee,resolved,notes,photo,completed_date,confirmed_at,version,sheet_row,sheet_hash) VALUES ('76856e71-664c-4e12-aed9-9b16743d601e','2026-09-30','Young guama plant on the market terrace leaning and needing support.','The young stem lacks support; the reason for the lean is not confirmed.','Install a sturdy stake beside the guama without damaging its roots. Gently bring the stem upright and tie it to the stake with a soft, loose figure-eight tie; leave room for growth and check the tie regularly.','Roberto ',1,'30/09/2026: Photo shows the young guama leaning over the mulched ground near other plants. Support requested; no assignee or completion reported.','/api/inspection-photo?key=ae226b6d-c0a4-4a2e-9b56-b6456e4e7fa2','2026-09-30',NULL,'4b436a27164051b835cd145080bc869c3982f40f53a01ac6be0ce649d1ac66a3',NULL,NULL);
