INSERT OR IGNORE INTO inspections (id,date,issue,cause,solution,assignee,resolved,notes,photo,completed_date,confirmed_at,version,sheet_row,sheet_hash) VALUES ('source-10','2026-09-29','Tall pepper plants in the garden bed tend to lean and fall over.','The stems have grown tall and need support to remain upright.','Gently tie each pepper stem to the ropes already placed along the outer edges of the bed, using loose ties that will not constrict the stems. Check that the plants remain upright. Harvest the chili peppers for next week.','Roberto ',1,'29/09/2026: Photo shows several pepper plants. Initial image-based note described drooping and mottled leaves and suggested checking their condition. 29/09/2026: Roberto clarified that the task is structural support: the plants are tall and tend to fall. Ropes are already in place along the outer edges of the bed; Pauline and MJ should tie the stems to them. 29/09/2026: Roberto also requested harvesting the chili peppers for next week.','/api/inspection-photo?key=e26eb67a-f7f3-48aa-b46e-85fdb3d32b76','2026-09-30',NULL,'be5488cae018c64cadc21a34b6f05cf4747dbba47a3af9a52f265d214aee83c4',NULL,NULL);
INSERT OR IGNORE INTO inspections (id,date,issue,cause,solution,assignee,resolved,notes,photo,completed_date,confirmed_at,version,sheet_row,sheet_hash) VALUES ('source-11','2026-09-29','Test the new irrigation system.','','Run a test cycle and check that the valves, lines and emitters deliver water evenly. Inspect for leaks or blocked sections, then record any faults.','',0,'','',NULL,NULL,'1',NULL,NULL);
INSERT OR IGNORE INTO inspections (id,date,issue,cause,solution,assignee,resolved,notes,photo,completed_date,confirmed_at,version,sheet_row,sheet_hash) VALUES ('source-12','2026-09-29','Market terrace sector overgrown with weeds; soil preparation and planting needed.','','Clear the weeds, open and loosen the soil with a spade and digging fork, then plant the sciuzzi and artichoke offshoots.','',0,'29/09/2026: Photo shows green ground vegetation, dry cut material, exposed soil and a visible irrigation hose in this market terrace sector. Identify plants to keep before clearing; the photo does not confirm planting or irrigation performance. Photo link pending.','',NULL,NULL,'70364338394ca161d1dbefcf81b8a23eaf8c160447d6f4d9562e8217fc86be73',NULL,NULL);
INSERT OR IGNORE INTO inspections (id,date,issue,cause,solution,assignee,resolved,notes,photo,completed_date,confirmed_at,version,sheet_row,sheet_hash) VALUES ('source-7','2026-09-29','Garden beds with young plants and drip irrigation lines; watering to be checked.','','Check soil moisture beside the seedlings and water the beds as needed; confirm that the drip lines deliver water evenly.','Roberto',1,'29/09/2026: Photo shows young plants beside drip lines. Soil in the right-hand bed looks darker in places; the image alone does not confirm whether watering is running or complete.','/api/inspection-photo?key=44306fbd-d03c-49d8-9efb-4a4eb2a21ae5','2026-09-30',NULL,'8aac96abdfa007ea782eaa9106fd843737b8666ca970e9c74ff71dc1632e1f86',NULL,NULL);
INSERT OR IGNORE INTO inspections (id,date,issue,cause,solution,assignee,resolved,notes,photo,completed_date,confirmed_at,version,sheet_row,sheet_hash) VALUES ('source-8','2026-09-29','Weeds in the herb beds.','','Weed the herb beds, removing weeds around the herbs without disturbing their roots.','Sanne',1,'29/09/2026: Weeding requested. No assignee or completion reported. 29/09/2026: Photo shows scattered grass-like weeds and small volunteers in and beside the herb beds, especially along the left drip lines; the planted herbs remain visible.','/api/inspection-photo?key=393f0055-3026-48e5-898e-116b5d8aba3e','2026-09-30',NULL,'82ba4264c669d276ca69b6414465e1a7eb4214fff3022a77243404bf08ee6e92',NULL,NULL);
INSERT OR IGNORE INTO inspections (id,date,issue,cause,solution,assignee,resolved,notes,photo,completed_date,confirmed_at,version,sheet_row,sheet_hash) VALUES ('source-9','2026-09-29','Weeds and dense ground vegetation in the fence garden bed beside the stone border.','','Weed the fence garden around the established plants and trees, taking care not to damage roots or stems.','Pauline and MJ',1,'29/09/2026: Photo shows dense low vegetation along the bed by the stone border and fence. Weed species are not confirmed from this overview; identify crop and volunteer plants before removing them.','/api/inspection-photo?key=c534d4a6-1dc7-455b-868c-4e96d6c3a88f','2026-09-30',NULL,'18ec67c41fa8f7d325fa395d5a3d9401c2c8841fec91ab4b3c7037f60f2a8413',NULL,NULL);
INSERT OR IGNORE INTO inspections (id,date,issue,cause,solution,assignee,resolved,notes,photo,completed_date,confirmed_at,version,sheet_row,sheet_hash) VALUES ('source-2','2026-09-28','Passion fruit vines growing chaotically outside the fence and extending over the path.','Likely lack of regular training along the fence; cause not confirmed.','Weave the flexible shoots back through the fence and guide them along its inside.','Suggested: Pauline and MJ',0,'28/09/2026: Shoots visible outside the fence above the stone wall.','/api/inspection-photo?key=0fe4c912-cfff-476a-8eb8-24dba5de46cb',NULL,NULL,'a8b2ba54fccec3f2c4346ccb2073ec69abc06c8f9fbde0d1f9d3b20144b52659',NULL,NULL);
INSERT OR IGNORE INTO inspections (id,date,issue,cause,solution,assignee,resolved,notes,photo,completed_date,confirmed_at,version,sheet_row,sheet_hash) VALUES ('source-3','2026-09-28','Pallets and loose wooden boards piled in the blue skip.','','Collect the reusable pallets and store them in a designated dry, orderly place.','Roberto',1,'28/09/2026: Pallets are stacked with loose timber in the blue skip; additional bags and materials are visible around it.','/api/inspection-photo?key=f9417883-c1e6-4ec5-bc96-58bbb7560ef6','2026-09-30',NULL,'20f4100bfa8acfd25f278e3511803535b07a259e70a35922675375b8822a848d',NULL,NULL);
INSERT OR IGNORE INTO inspections (id,date,issue,cause,solution,assignee,resolved,notes,photo,completed_date,confirmed_at,version,sheet_row,sheet_hash) VALUES ('source-4','2026-09-28','Ornamental plants in poor condition; mildew reported, without a confirmed diagnosis.','Suspected mildew; pathogen and extent of infection not confirmed.','Ask the supplier to add one pack of Fosetil-Al to the existing quote for a possible targeted emergency treatment in the ornamental gardens. Confirm the diagnosis and product label suitability before use.','Roberto',1,'28/09/2026: Roberto to ask the supplier to add one pack to the quote; supplier has not been contacted through this record. Brands mentioned: Aliette, Massó Garden, Compo Fitoftora. Systemic action and suitability in humid conditions were proposed by the reporter; diagnosis and product label still need checking.','','2026-09-30',NULL,'24bce83d9fcfc6a283a2fa31ccf6ce374103e3b56f0386dab33bd38c9a3724f6',NULL,NULL);
